  // ComputeEffectiveDimension (backPlateAPI.cpp:567-596).
  computeEffectiveDimension(computeWidth: boolean, time?: number): number {
    const scale = f32Vec(readAt(this.getScaleTweakAttr(), time), 2)
    const camera = Camera.getCamera(this.prim, time)
    let aperture: number
    let scaleFactor: number
    if (computeWidth) {
      aperture = Math.fround(camera.horizontalAperture)
      scaleFactor = scale[0]!
    } else {
      aperture = Math.fround(camera.verticalAperture)
      scaleFactor = scale[1]!
    }
    if (camera.projection === 'orthographic') {
      return Math.fround(aperture * scaleFactor)
    }
    const focalLength = Math.fround(Math.fround(camera.focalLength) * GfCameraValue.FOCAL_LENGTH_UNIT)
    // Calculate the ratio of the aperture to the focal length and then
    // multiply by the focus distance and scaling factor to get the actual
    // dimension. float * float promotes to double at APERTURE_UNIT.
    const focusTimesAperture = Math.fround(Math.fround(camera.focusDistance) * aperture)
    return Math.fround(
      focusTimesAperture * GfCameraValue.APERTURE_UNIT * scaleFactor / focalLength)
  }

  // SetAspectRatio (backPlateAPI.cpp:598-613). As upstream, the new scale is
  // authored at the default time.
  setAspectRatio(width: number, height: number, time?: number): void {
    const scale = f32Vec(readAt(this.getScaleTweakAttr(), time), 2)
    const computedWidth = this.computeEffectiveDimension(true, time)
    const computedHeight = this.computeEffectiveDimension(false, time)
    const adjustWidthFactor = Math.fround(Math.fround(width) / computedWidth)
    const adjustHeightFactor = Math.fround(Math.fround(height) / computedHeight)
    scale[0] = Math.fround(scale[0]! * adjustWidthFactor)
    scale[1] = Math.fround(scale[1]! * adjustHeightFactor)
    this.getScaleTweakAttr().set(scale)
  }

  // SetCameraSpacePosition (backPlateAPI.cpp:615-620).
  setCameraSpacePosition(pos: readonly number[], time?: number): void {
    const focusDistance = Math.fround(Camera.getCamera(this.prim, time).focusDistance)
    const translation = [
      Math.fround(pos[0]!), Math.fround(pos[1]!), Math.fround(Math.fround(pos[2]!) - focusDistance),
    ]
    writeAt(this.getTranslateTweakAttr(), translation, time)
  }

  // GetCameraSpacePosition (backPlateAPI.cpp:622-628).
  getCameraSpacePosition(time?: number): Vec3 {
    const focusDistance = Math.fround(Camera.getCamera(this.prim, time).focusDistance)
    const position = f32Vec(readAt(this.getTranslateTweakAttr(), time), 3)
    return [position[0]!, position[1]!, Math.fround(position[2]! + focusDistance)]
  }

  // SetWorldSpacePosition (backPlateAPI.cpp:630-636).
  setWorldSpacePosition(pos: readonly number[], time?: number): void {
    const xform = this._worldTranslation(time)
    this.setCameraSpacePosition(
      [0, 1, 2].map(i => Math.fround(Math.fround(pos[i]!) - xform[i]!)), time)
  }

  // GetWorldSpacePosition (backPlateAPI.cpp:638-644).
  getWorldSpacePosition(time?: number): Vec3 {
    const xform = this._worldTranslation(time)
    const position = this.getCameraSpacePosition(time)
    return [0, 1, 2].map(i => Math.fround(position[i]! + xform[i]!)) as Vec3
  }

  // static_cast<GfVec3f>(ComputeLocalToWorldTransform(time).ExtractTranslation()).
  private _worldTranslation(time?: number): Vec3 {
    const m = new XformCache(time).getLocalToWorldTransform(this.prim)
    return [Math.fround(m[12]), Math.fround(m[13]), Math.fround(m[14])]
  }
