// UsdGeomBackPlateAPI — multiple-apply API schema describing a camera back
// plate (image, depth and luma adjustments, and placement tweaks).
// Reference: pxr/usd/usdGeom/backPlateAPI.{h,cpp} (OpenUSD v26.11.1).
//
// Properties are namespaced "backPlate:<instanceName>:<baseName>"
// (tokens.cpp:16-29). The custom-code computations (backPlateAPI.cpp:567-646)
// read the camera schema on the same prim at the given time and use float
// (GfVec3f / float) arithmetic, mirrored here with Math.fround. A time of
// undefined is UsdTimeCode::Default().



import { GfCamera as GfCameraValue } from 'typescript-usd/gf/camera'
import { Camera } from './camera.ts'
import { XformCache } from './xformCache.ts'
import { plain } from './valueUtils.ts'

const NAMESPACE = 'backPlate'
const INSTANCE = '__INSTANCE_NAME__'

// UsdGeomTokens backPlate_MultipleApplyTemplate_* (tokens.cpp:17-29), in
// GetSchemaAttributeNames order (backPlateAPI.cpp:500-524).
const TEMPLATES = {
  scaleTweak: `${NAMESPACE}:${INSTANCE}:scale:tweak`,
  rotateXYZTweak: `${NAMESPACE}:${INSTANCE}:rotateXYZ:tweak`,
  translateTweak: `${NAMESPACE}:${INSTANCE}:translate:tweak`,
  image: `${NAMESPACE}:${INSTANCE}:image`,
  alphaImage: `${NAMESPACE}:${INSTANCE}:alpha:image`,
  depthImage: `${NAMESPACE}:${INSTANCE}:depth:image`,
  depthMinOffset: `${NAMESPACE}:${INSTANCE}:depth:minOffset`,
  depthNormalizingFactor: `${NAMESPACE}:${INSTANCE}:depth:normalizingFactor`,
  depthCameraSpaceOffset: `${NAMESPACE}:${INSTANCE}:depth:cameraSpaceOffset`,
  lumaSlope: `${NAMESPACE}:${INSTANCE}:luma:slope`,
  lumaOffset: `${NAMESPACE}:${INSTANCE}:luma:offset`,
  lumaPower: `${NAMESPACE}:${INSTANCE}:luma:power`,
  plateVisibility: `${NAMESPACE}:${INSTANCE}:plateVisibility`,
} as const
type TemplateKey = keyof typeof TEMPLATES

const TYPES: Record<TemplateKey, string> = {
  scaleTweak: 'float2', rotateXYZTweak: 'float3', translateTweak: 'float3',
  image: 'asset', alphaImage: 'asset', depthImage: 'asset',
  depthMinOffset: 'float', depthNormalizingFactor: 'float', depthCameraSpaceOffset: 'float',
  lumaSlope: 'float3', lumaOffset: 'float3', lumaPower: 'float3', plateVisibility: 'token',
}

// UsdSchemaRegistry::MakeMultipleApplyNameInstance.
function makeInstance(template: string, instanceName: string): string {
  return template.replace(INSTANCE, instanceName)
}

// UsdSchemaRegistry::GetMultipleApplyNameTemplateBaseName: the part after
// the instance-name placeholder.
function templateBaseName(template: string): string {
  return template.slice(template.indexOf(INSTANCE) + INSTANCE.length + 1)
}

type Vec3 = [number, number, number]

function f32Vec(v: unknown, size: number): number[] {
  const p = plain(v)
  const out: number[] = []
  for (let i = 0; i < size; i++) out.push(Math.fround(Array.isArray(p) ? Number(p[i] ?? 0) : 0))
  return out
}


function readAt(attr: Attribute, time: number | undefined): unknown {
  return time === undefined ? attr.getValue() : attr.getValueAtTime(time)
}

function writeAt(attr: Attribute, value: unknown, time: number | undefined): void {
  if (time === undefined) attr.set(value)
  else attr.setTimeSample(time, value)
}
